//! Approval-bounded performance/reliability copilot for Worldgen P21.
use super::performance_reliability_support::{self, CapabilityWorkloadRequest4, ReliableCapabilityResult6};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.performance-reliability-copilot-receipt+json";
const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityCopilotRequest{pub reliability_request:CapabilityWorkloadRequest4,pub workload_order:Vec<String>,pub workload_budget:u64,pub dry_run:bool,pub signed_approval:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub workload_order:Vec<String>,pub admitted_workload_order:Vec<String>,pub denied_workload_order:Vec<String>,pub reliability_disposition:String,pub reliability_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PerformanceReliabilityCopilotError{#[error("invalid reliability copilot request: {0}")]Invalid(String),#[error("reliability assessment failed: {0}")]Reliability(String),#[error("reliability copilot artifact failed: {0}")]Artifact(String),#[error("invalid reliability copilot receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl PerformanceReliabilityCopilotReceipt{pub fn validate(&self)->Result<(),PerformanceReliabilityCopilotError>{if self.schema_version!="aurora-research-contract/1.0"||self.boundary!=BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workload_order.is_empty()||![&self.reliability_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h)||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(PerformanceReliabilityCopilotError::Receipt("reliability copilot identity or digest is incomplete".into()))}for v in [&self.workload_order,&self.admitted_workload_order,&self.denied_workload_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(PerformanceReliabilityCopilotError::Receipt("reliability copilot ordering is not canonical".into()))}}let ids=self.workload_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_workload_order.iter().chain(&self.denied_workload_order).cloned().collect::<BTreeSet<_>>();if ids!=parts{return Err(PerformanceReliabilityCopilotError::Receipt("reliability copilot workloads do not partition".into()))}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":"aurora-research-contract/1.0","capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["reliability engineer","workflow orchestrator","research program lead"],"behavior":format!("run approval-bounded reliability actions for {scale}"),"value":"turns workload reliability evidence into a replayable budgeted decision without hidden retries or claims of completion","input_schema":"PerformanceReliabilityCopilotRequest1@1","output_schema":"PerformanceReliabilityCopilotReceipt1@1","effects":["invoke:bounded-reliability-tool","block:unsafe-release"],"permissions":["invoke:declared-reliability-tool"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
pub fn run(r:&PerformanceReliabilityCopilotRequest,feature_id:&str,version:&str,_scale:&str,require_approval:bool)->Result<PerformanceReliabilityCopilotReceipt,PerformanceReliabilityCopilotError>{if r.boundary!=BOUNDARY||r.workload_order.is_empty()||r.workload_order!={let mut x=r.workload_order.clone();x.sort();x.dedup();x}||r.workload_budget==0||!r.reliability_request.raw_data_local||!r.reliability_request.aggregate_only{return Err(PerformanceReliabilityCopilotError::Invalid("reliability copilot request is invalid".into()))}let reliability=performance_reliability_support::assess_performance_reliability(&r.reliability_request).map_err(|e|PerformanceReliabilityCopilotError::Reliability(e.to_string()))?;let mut omissions=reliability.omission_order.clone();let approved=!require_approval||r.signed_approval;if !approved{omissions.push("copilot:approval-missing".into())}if r.dry_run{omissions.push("copilot:dry-run-no-effect".into())}if r.workload_order.len()as u64>r.workload_budget{omissions.push("copilot:workload-budget-exceeded".into())}omissions.sort();omissions.dedup();let safe=reliability.disposition=="qualified"&&approved&&r.workload_order.len()as u64<=r.workload_budget;let disposition=if safe{"qualified"}else{"blocked"};let admitted=if safe{r.workload_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{r.workload_order.clone()};let effects=if safe{vec![format!("invoke:bounded-reliability-tool:{}",reliability.result_digest)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":version,"feature_id":feature_id,"request_id":r.reliability_request.request_id,"disposition":disposition,"workload_order":r.workload_order,"admitted_workload_order":admitted,"denied_workload_order":denied,"reliability_disposition":reliability.disposition,"reliability_digest":reliability.result_digest,"replay_identity":reliability.replay_identity,"omissions":omissions,"uncertainty":reliability.uncertainty_order,"negative_evidence":reliability.negative_evidence_order,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|PerformanceReliabilityCopilotError::Artifact(e.to_string()))?;let strings=|k:&str|payload[k].as_array().map(|a|a.iter().filter_map(|v|v.as_str().map(String::from)).collect()).unwrap_or_default();let out=PerformanceReliabilityCopilotReceipt{schema_version:"aurora-research-contract/1.0".into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.reliability_request.request_id.clone(),disposition:disposition.into(),workload_order:r.workload_order.clone(),admitted_workload_order:admitted,denied_workload_order:denied,reliability_disposition:reliability.disposition,reliability_digest:reliability.result_digest,copilot_digest:d.clone(),replay_identity:reliability.replay_identity,omissions:strings("omissions"),uncertainty:reliability.uncertainty_order,negative_evidence:reliability.negative_evidence_order,effect_receipts:effects,artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into()};out.validate()?;Ok(out)}

